#pragma once

// ============================================================
// Engine Commands Repository
// ============================================================
//
// Contains logical actuator commands generated by the
// Control Algorithms.
//
// Field ownership:
//   starterCommand   -> Starter Control Algorithm
//   fuelPumpCommand  -> Fuel Control Algorithm
//   gasValveCommand  -> Gas Control Algorithm
//   fuelValveCommand -> Fuel Control Algorithm
//   glowPlugCommand  -> Ignition Control Algorithm
//
// Hardware-specific translation is performed by the HAL.
//
// ============================================================

struct EngineCommands
{
    float starterCommand;     // Starter command: 0.0 ... 100.0 %
    float fuelPumpCommand;    // Fuel pump command: 0.0 ... 100.0 %

    bool gasValveCommand;     // Gas valve logical command
    bool fuelValveCommand;    // Fuel shut-off valve logical command
    bool glowPlugCommand;     // Glow plug logical command
};

// Global repository instance
extern EngineCommands g_engineCommands;